import assert from 'node:assert/strict';import fs from 'node:fs/promises';import path from 'node:path';
import {loadEnv,preflight}from '../lib/env.mjs';import {createSession}from '../lib/harness.mjs';
const env=await loadEnv();assert.ok(['localhost','127.0.0.1'].includes(new URL(env.baseUrl).hostname));await preflight(env);const red=process.env.QA_QUOTATION_IDENTITY_RED==='1';const draft=red?'1.1':'not-a-number';const output=path.resolve(process.env.QA_QUOTATION_IDENTITY_OUTPUT_DIR||'qa/2026-10-01_comprehensive-audit_ui35-identity-final');await fs.mkdir(output,{recursive:true});const ctx=await createSession({env,role:'ADMIN',evidenceDir:output,runId:'UI35-IDENTITY'});const proof={role:ctx.role,account:ctx.username,states:[],writes:[]};const save=async()=>fs.writeFile(path.join(output,'driver-assertions.json'),JSON.stringify({...proof,errors:ctx.errors},null,2)+'\n');
async function read(){const result=[];for(const id of[45,43]){const r=await ctx.apiGet(`/quotations/${id}`);assert.equal(r.status,200);result.push(r);}return result;}
async function select(view){const h=await ctx.page.evaluateHandle(name=>[...document.querySelectorAll('.quotation-frames tbody tr')].find(e=>e.textContent.includes(name)),view.templateName);const row=h.asElement();assert.ok(row);await row.click();await ctx.page.waitForFunction(name=>document.querySelector('.quotation-frames .is-selected')?.textContent.includes(name)&&document.querySelector('.quotation-route-block input'),{},view.templateName);await ctx.settle(250);}
async function capture(width,label){const shot=await ctx.screenshot(`${width}-${label}`);const dom=await ctx.page.evaluate(()=>({url:location.pathname,text:document.body.innerText,values:[...document.querySelectorAll('.quotation-route-block input')].map(e=>({label:e.getAttribute('aria-label'),value:e.value})),selected:document.querySelector('.quotation-frames .is-selected')?.innerText}));const domPath=shot.replace(/\.png$/,'-dom.json');await fs.writeFile(domPath,JSON.stringify(dom,null,2)+'\n');proof.states.push({width,label,shot,domPath,dom});await save();return dom;}
try{await ctx.page.setRequestInterception(true);ctx.page.on('request',r=>{if(['POST','PUT','PATCH','DELETE'].includes(r.method())){proof.writes.push({method:r.method(),url:r.url(),body:JSON.parse(r.postData()||'{}'),materialWrite:false});void r.abort('blockedbyclient');}else void r.continue();});const before=await read();proof.before=before;const own=before[0].body,other=before[1].body;const label=`Hệ số ${own.cells[0].routeName} ${own.cells[0].vehicleSizeClassCode}`;for(const width of(red?[390]:[390,768,1440])){await ctx.page.setViewport({width,height:900,hasTouch:width<900});await ctx.goto('/config/quotations');await select(other);await select(own);const input=await ctx.page.$(`[aria-label="${label}"]`);assert.ok(input);await input.click();const length=await input.evaluate(e=>e.value.length);for(let i=0;i<length;i++)await ctx.page.keyboard.press('ArrowRight');for(let i=0;i<length;i++)await ctx.page.keyboard.press('Backspace');assert.equal(await input.evaluate(e=>e.value),'');await ctx.page.keyboard.type(draft);assert.equal(await input.evaluate(e=>e.value),draft);await capture(width,'quotation45-draft');await select(other);const dom=await capture(width,'quotation43-selected');const current=dom.values.find(e=>e.label===label);assert.ok(current);if(red){assert.equal(current.value,'1.1','Retain actual stale-draft repro');}else{assert.equal(current.value,String(other.cells[0].heSo));await select(own);const returned=await capture(width,'quotation45-returned');assert.equal(returned.values.find(e=>e.label===label).value,String(own.cells[0].heSo));}}
if(!red){assert.equal(proof.writes.length,0);assert.equal(ctx.errors.length,0);}assert.deepEqual(await read(),before);proof.after=await read();proof.complete=true;await save();console.log(JSON.stringify({complete:true,redReproduced:red,states:proof.states.length,materialWrites:0,blockedBlurWrites:proof.writes.length}));}finally{await save();await ctx.browser.close();}
